import { Component, DestroyRef, inject, signal, computed, OnInit, effect, untracked } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute, Router } from '@angular/router';
import { ReactiveFormsModule, FormBuilder, FormGroup } from '@angular/forms';
import { DomSanitizer, SafeResourceUrl } from '@angular/platform-browser';
import { DocumentUploaderComponent } from '../../../shared/components/document-uploader/document-uploader';
import { SolicitudService, SolicitudFormValue } from '../../../shared/services/solicitud.service';
import { DocumentoService, TipoDocumento } from '../../../services/documento.service';
import { UppercaseDirective } from '../../../shared/directives/uppercase.directive';
import { environment } from '../../../../environments/environment';
import { FirmaEfirmaModalComponent, DocumentoAFirmar, ResultadoFirma } from '../../../shared/components/firma-efirma-modal/firma-efirma-modal.component';
import { SignMetadata } from '../../../shared/utils/pdf-sign.util';
import { PersonalidadJuridica, createFisicaForm, createMoralForm } from '../../../shared/models/solicitud-forms';
import { Solicitud, DocumentoResumen } from '../../../shared/models/solicitud.model';
import { ObservacionesService } from '../../../shared/services/observaciones.service';
import { Observacion, ObservacionTarget } from '../../../shared/models/observacion.model';
import { ObservacionSidebarComponent } from '../../../shared/components/observacion-sidebar/observacion-sidebar.component';
import { extractErrorMessage } from '../../../shared/utils/error-utils';

@Component({
  selector: 'app-editar-solicitud',
  imports: [
    ReactiveFormsModule,
    DocumentUploaderComponent,
    FirmaEfirmaModalComponent,
    UppercaseDirective,
    ObservacionSidebarComponent,
  ],
  templateUrl: './editar-solicitud.component.html',
})
export class EditarSolicitudComponent implements OnInit {
  private fb = inject(FormBuilder);
  private router = inject(Router);
  private route = inject(ActivatedRoute);
  private sanitizer = inject(DomSanitizer);
  private solicitudService = inject(SolicitudService);
  private documentoService = inject(DocumentoService);
  private obsService = inject(ObservacionesService);
  private readonly destroyRef = inject(DestroyRef);

  readonly folio = this.route.snapshot.paramMap.get('id') ?? '';

  solicitud = signal<Solicitud | null>(null);
  personalidadJuridica = signal<PersonalidadJuridica>('fisica');
  isSubmitting = signal(false);
  submitSuccess = signal(false);
  submitError = signal<string | null>(null);
  previewUrl = signal<SafeResourceUrl | null>(null);
  previewTitle = signal<string>('');
  showPreviewModal = signal<boolean>(false);
  nombreProyecto = signal('');
  showFirmaModal = signal(false);
  isSigning = signal(false);
  signError = signal<string | null>(null);
  docsParaFirmar = signal<DocumentoAFirmar[]>([]);
  signedClaves = signal<string[]>([]);
  firmaMetadata = signal<SignMetadata | undefined>(undefined);
  isLoading = signal(true);

  tiposDocumento = signal<TipoDocumento[]>([]);
  documentosMap = signal<Record<string, { file: File | null; id: number | null }>>({});
  documentosOriginales = signal<DocumentoResumen[]>([]);

  fisicaForm: FormGroup = createFisicaForm(this.fb);
  moralForm: FormGroup = createMoralForm(this.fb);

  readonly documentosObservados = signal<number[]>([]);
  resaltado = signal<string | null>(null);

  constructor() {
    effect(() => {
      const documentos = this.documentosOriginales();
      const tipos = this.tiposDocumento();
      if (documentos.length > 0 && tipos.length > 0) {
        untracked(() => this.buildDocumentosMap(documentos));
      }
    });

    effect(() => {
      const obs = this.observaciones();
      untracked(() => {
        const obsPending = obs
          .filter(o => o.status === 'pendiente' && o.target.type === 'document')
          .map(o => (o.target as { type: 'document'; documentId: number }).documentId);
        this.documentosObservados.set(obsPending);
      });
    });
  }

  get activeForm(): FormGroup {
    return this.isMoral() ? this.moralForm : this.fisicaForm;
  }

  isMoral = computed(() => this.personalidadJuridica() === 'moral');

  readonly SECTION_LABELS: Record<string, string> = {
    'info-general': 'Datos del inversionista',
    proyecto: 'Información del proyecto',
    documentos: 'Documentos adjuntos',
  };

  observacionesParaCampo(fieldId: string): Observacion[] {
    return this.observaciones().filter(
      (o) => o.target.type === 'field' && o.target.fieldId === fieldId,
    );
  }

  seccionTieneObsPendiente(sectionId: string): boolean {
    return this.observaciones().some(
      (o) =>
        o.target.type === 'section' &&
        o.target.sectionId === sectionId &&
        o.status === 'pendiente',
    );
  }

  documentoTieneObsPendiente(docId: number | null): boolean {
    if (docId == null) return false;
    return this.observaciones().some(
      (o) =>
        o.target.type === 'document' &&
        (o.target as { type: 'document'; documentId: number }).documentId === docId &&
        o.status === 'pendiente',
    );
  }

  slugify(s: string): string {
    return s
      .toLowerCase()
      .normalize('NFD')
      .replace(/[\u0300-\u036f]/g, '')
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '');
  }

  private getDocumentNameById(docId: number): string {
    const doc = this.documentosOriginales().find(d => d.id === docId);
    return doc?.nombreOriginal ?? String(docId);
  }

  alIrA(target: ObservacionTarget): void {
    let id: string;
    switch (target.type) {
      case 'field':
        id = `field-${target.fieldId}`;
        this.resaltado.set(target.fieldId);
        break;
      case 'section':
        id = `section-${target.sectionId}`;
        this.resaltado.set(target.sectionId);
        break;
      case 'document':
        id = `documento-${this.slugify(this.getDocumentNameById(target.documentId))}`;
        this.resaltado.set(String(target.documentId));
        break;
    }
    const el = document.getElementById(id);
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
    if (el) {
      const focusable = el.matches('input,textarea,button,select,a,[tabindex]')
        ? el
        : el.querySelector<HTMLElement>('input,textarea,button,select,a,[tabindex]');
      focusable?.focus({ preventScroll: true });
    }
    setTimeout(() => this.resaltado.set(null), 2000);
  }

  // eslint-disable-next-line @typescript-eslint/no-empty-function
  onObservacionCorregida(): void {
  }

  documentosInversionista = computed(() => {
    const activePersonality = this.personalidadJuridica();
    return this.tiposDocumento().filter(tipo =>
      tipo.tab === 'inversionista' &&
      (tipo.personalidad === null || tipo.personalidad === activePersonality)
    );
  });

  observaciones = computed<Observacion[]>(() =>
    this.obsService.observacionesDe(this.folio),
  );

  stepOneValid(): boolean {
    if (!this.activeForm.valid) return false;
    const requiredDocs = this.documentosInversionista().filter(tipo => tipo.requerido);
    const docs = this.documentosMap();
    return requiredDocs.every(tipo => docs[tipo.clave]?.id !== undefined && docs[tipo.clave]?.id !== null);
  }

  ngOnInit() {
    this.loadSolicitud();
    this.loadTiposDocumento();
    this.obsService.cargar(this.folio);
  }

  private loadSolicitud(): void {
    this.solicitudService.getByFolio(this.folio).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (sol) => {
        this.solicitud.set(sol);
        this.nombreProyecto.set(sol.proyecto || '');

        if (sol.personalidadJuridica === 'moral') {
          this.personalidadJuridica.set('moral');
          this.moralForm.patchValue({
            denominacionRazonSocial: sol.denominacionRazonSocial || '',
            rfc: sol.rfc || '',
            correoElectronico: sol.email || '',
            confirmarCorreo: sol.email || '',
            numeroFolio: sol.numeroFolio || '',
            fechaOtorgamiento: sol.fechaOtorgamiento || '',
            nombreRepresentante: sol.nombreRepresentante || '',
            primerApellidoRepresentante: sol.primerApellidoRepresentante || '',
            segundoApellidoRepresentante: sol.segundoApellidoRepresentante || '',
          });
        } else {
          this.personalidadJuridica.set('fisica');
          this.fisicaForm.patchValue({
            nombreCompleto: sol.solicitante || '',
            rfc: sol.rfc || '',
            correoElectronico: sol.email || '',
            confirmarCorreo: sol.email || '',
            tieneRepresentanteLegal: sol.tieneRepresentanteLegal ?? false,
            nombreRepresentante: sol.nombreRepresentante || '',
            primerApellidoRepresentante: sol.primerApellidoRepresentante || '',
            segundoApellidoRepresentante: sol.segundoApellidoRepresentante || '',
          });
        }

        this.documentosOriginales.set(sol.documentos);
        this.isLoading.set(false);
      },
      error: () => {
        this.submitError.set('No se pudo cargar la solicitud.');
        this.isLoading.set(false);
      },
    });
  }

  private loadTiposDocumento(): void {
    this.documentoService.getTiposDocumento().pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: (tipos) => {
        this.tiposDocumento.set(tipos);
      },
      error: () => {
        this.submitError.set('Error al cargar la configuración de los documentos.');
      }
    });
  }

  private buildDocumentosMap(documentos: DocumentoResumen[]): void {
    const map: Record<string, { file: File | null; id: number | null }> = {};

    for (const doc of documentos) {
      const clave = doc.tipoDocumento?.clave;
      if (clave) {
        map[clave] = {
          file: this.createPlaceholderFile(doc.nombreOriginal),
          id: doc.id,
        };
      }
    }
    this.documentosMap.set(map);
  }

  private createPlaceholderFile(nombre: string): File {
    const file = new File([], nombre, { type: 'application/pdf' });
    Object.defineProperty(file, 'size', { value: 0, writable: false });
    return file;
  }

  getFile(clave: string): File | null {
    return this.documentosMap()[clave]?.file ?? null;
  }

  getDocumentId(clave: string): number | null {
    return this.documentosMap()[clave]?.id ?? null;
  }

  onFileChange(clave: string, file: File | null) {
    this.documentosMap.update(map => ({
      ...map,
      [clave]: {
        file,
        id: map[clave]?.id ?? null
      }
    }));
  }

  onIdChange(clave: string, id: number | null) {
    this.documentosMap.update(map => ({
      ...map,
      [clave]: {
        file: map[clave]?.file ?? null,
        id
      }
    }));
  }

  private archivoTieneBytesReales(file: File | null): boolean {
    return !!file && file.slice().size > 0;
  }

  viewFile(file: File | null, title: string, documentId?: number | null) {
    if (!file) return;
    if (documentId && !this.archivoTieneBytesReales(file)) {
      const fileUrl = `${environment.apiUrl}/documentos/${documentId}`;
      this.previewUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(fileUrl));
    } else {
      const fileUrl = URL.createObjectURL(file);
      this.previewUrl.set(this.sanitizer.bypassSecurityTrustResourceUrl(fileUrl));
    }
    this.previewTitle.set(title);
    this.showPreviewModal.set(true);
  }

  closePreviewModal() {
    this.showPreviewModal.set(false);
    this.previewUrl.set(null);
    this.previewTitle.set('');
  }

  onSubmit() {
    if (!this.activeForm.valid) {
      this.activeForm.markAllAsTouched();
      return;
    }

    const docs = this.collectDocsForSigning();
    if (docs.length > 0) {
      this.isSubmitting.set(true);
      this.submitError.set(null);
      this.signError.set(null);
      this.leerDocumentosParaFirma(docs);
    } else {
      this.saveChanges();
    }
  }

  private collectDocsForSigning(): { clave: string; nombre: string; file: File }[] {
    const observed = this.documentosObservados();
    const allClaves = [
      ...this.documentosInversionista().map(d => d.clave),
    ];
    const docsMap = this.documentosMap();
    return allClaves
      .filter(clave => {
        const docId = docsMap[clave]?.id;
        return docId != null && observed.includes(docId);
      })
      .map(clave => {
        const entry = docsMap[clave];
        if (!entry?.file || !this.archivoTieneBytesReales(entry.file)) return null;
        return { clave, nombre: this.getNombreByClave(clave), file: entry.file };
      })
      .filter((doc): doc is { clave: string; nombre: string; file: File } => doc !== null);
  }

  private getNombreByClave(clave: string): string {
    const allDocs = [...this.documentosInversionista()];
    const tipo = allDocs.find(t => t.clave === clave);
    return tipo?.nombre ?? clave;
  }

  private leerDocumentosParaFirma(docs: { clave: string; nombre: string; file: File }[]): void {
    const documentos: (DocumentoAFirmar & { clave: string })[] = [];
    const docsMap = this.documentosMap();
    let index = 0;

    const procesarSiguiente = (): void => {
      if (index >= docs.length) {
        if (documentos.length > 0) {
          const sol = this.solicitud();
          if (sol) {
            this.firmaMetadata.set({
              solicitudId: sol.id,
              rfc: sol.rfc,
              createdAt: sol.createdAt,
            });
          }
          this.docsParaFirmar.set(documentos);
          this.showFirmaModal.set(true);
        } else {
          this.saveChanges();
        }
        return;
      }

      const doc = docs[index];
      const entry = docsMap[doc.clave];

      if (entry?.id == null) {
        index++;
        procesarSiguiente();
        return;
      }

      if (doc.file && this.archivoTieneBytesReales(doc.file)) {
        doc.file.arrayBuffer().then(buffer => {
          documentos.push({ nombre: doc.nombre, bytes: new Uint8Array(buffer), clave: doc.clave });
          index++;
          procesarSiguiente();
        });
        return;
      }

      this.documentoService.downloadDocumento(entry.id).pipe(
        takeUntilDestroyed(this.destroyRef),
      ).subscribe({
        next: (bytes) => {
          documentos.push({ nombre: doc.nombre, bytes, clave: doc.clave });
          index++;
          procesarSiguiente();
        },
        error: (err) => {
          this.signError.set(extractErrorMessage(err));
        },
      });
    };

    procesarSiguiente();
  }

  onFirmaFirmado(resultados: ResultadoFirma[]) {
    this.showFirmaModal.set(false);
    this.isSigning.set(true);
    this.signError.set(null);

    const sol = this.solicitud();
    const docsMap = this.documentosMap();
    const serialsByClave: Record<string, string> = {};
    const resultadosByClave = new Map<string, ResultadoFirma>();
    for (const r of resultados) {
      if (r.clave) {
        resultadosByClave.set(r.clave, r);
      }
    }

    const pending = this.docsParaFirmar()
      .filter((d): d is DocumentoAFirmar & { clave: string } => !!d.clave && resultadosByClave.has(d.clave));
    let index = 0;

    const procesarSiguiente = (): void => {
      if (index >= pending.length) {
        this.saveChanges();
        return;
      }

      const doc = pending[index];
      const r = resultadosByClave.get(doc.clave)!;
      const existingDocId = docsMap[doc.clave]?.id;

      if (!existingDocId) {
        this.isSigning.set(false);
        this.signError.set('El documento no fue subido previamente.');
        return;
      }

      this.documentoService.firmarDocumento(existingDocId, r.signedBytes, r.serial, JSON.stringify({
        solicitudId: sol?.id ?? null,
        rfc: sol?.rfc ?? '',
        createdAt: sol?.createdAt ?? '',
      })).pipe(
        takeUntilDestroyed(this.destroyRef),
      ).subscribe({
        next: () => {
          serialsByClave[doc.clave] = r.serial;
          index++;
          procesarSiguiente();
        },
        error: (err) => {
          this.isSigning.set(false);
          this.signError.set(extractErrorMessage(err));
        },
      });
    };

    procesarSiguiente();
  }

  onFirmaCerrado() {
    this.showFirmaModal.set(false);
    this.docsParaFirmar.set([]);
    this.isSubmitting.set(false);
    this.submitError.set(null);
  }

  private saveChanges() {
    const formValue = this.activeForm.value as SolicitudFormValue;
    const payload: Record<string, unknown> = {};

    if (this.isMoral()) {
      payload['denominacion_razon_social'] = formValue.denominacionRazonSocial;
      payload['rfc'] = formValue.rfc;
      payload['correo_electronico'] = formValue.correoElectronico;
      payload['numero_folio'] = formValue.numeroFolio;
      payload['fecha_otorgamiento'] = formValue.fechaOtorgamiento;
      payload['nombre_representante'] = formValue.nombreRepresentante;
      payload['primer_apellido_representante'] = formValue.primerApellidoRepresentante;
      payload['segundo_apellido_representante'] = formValue.segundoApellidoRepresentante || null;
    } else {
      payload['nombre_completo'] = formValue.nombreCompleto;
      payload['rfc'] = formValue.rfc;
      payload['correo_electronico'] = formValue.correoElectronico;
      payload['tiene_representante_legal'] = formValue.tieneRepresentanteLegal;
      if (formValue.tieneRepresentanteLegal) {
        payload['nombre_representante'] = formValue.nombreRepresentante;
        payload['primer_apellido_representante'] = formValue.primerApellidoRepresentante;
        payload['segundo_apellido_representante'] = formValue.segundoApellidoRepresentante || null;
      }
    }
    payload['nombre_proyecto'] = this.nombreProyecto();

    this.solicitudService.actualizarSolicitud(this.folio, payload).pipe(
      takeUntilDestroyed(this.destroyRef),
    ).subscribe({
      next: () => {
        this.isSigning.set(false);
        this.isSubmitting.set(false);
        this.submitSuccess.set(true);
      },
      error: (err) => {
        this.isSigning.set(false);
        this.isSubmitting.set(false);
        this.submitError.set(extractErrorMessage(err));
      },
    });
  }

  goBack() {
    this.router.navigate(['/inversores/autorizaciones', this.folio]);
  }
}
